// Load Workbox from local vendored copy (generated by: deno task setup:workbox)
importScripts('/assets/js/workbox/workbox-v7.3.0/workbox-sw.js');

// Tell workbox-sw to load all modules from local path instead of CDN
workbox.setConfig({ modulePathPrefix: '/assets/js/workbox/workbox-v7.3.0/' });

const { setCacheNameDetails, clientsClaim } = workbox.core;
const { precacheAndRoute, cleanupOutdatedCaches } = workbox.precaching;
const { registerRoute } = workbox.routing;
const { NetworkFirst, StaleWhileRevalidate, CacheFirst } = workbox.strategies;
const { ExpirationPlugin } = workbox.expiration;

// ============================================
// CACHE NAMING
// ============================================
// Static cache names — no version hash so runtime caches persist across deploys.
// Precaching already handles versioning via file-revision hashes.
setCacheNameDetails({ prefix: 'kipukas-pwa' });

// ============================================
// LIFECYCLE: controlled skipWaiting via postMessage
// ============================================
// Do NOT call self.skipWaiting() automatically.
// The client (pwa-update-handler.js) will send a SKIP_WAITING message
// when the user chooses to update, giving them control over the timing.

// Track whether the PWA has been installed (persists for the SW lifetime).
let pwaInstalled = false;

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }

  // install_pwa.html notifies us when the user completes a PWA install.
  if (event.data && event.data.type === 'PWA_INSTALLED') {
    pwaInstalled = true;
  }

  // After install (or on a standalone launch), warm the full offline cache:
  // card art (.jxl) + the QR decoder, which are kept out of the lean precache.
  if (event.data && event.data.type === 'WARM_OFFLINE_CACHE') {
    event.waitUntil(warmOfflineCache());
  }

  // install_pwa.html asks us on page load whether the PWA was already installed.
  // Responds on the provided MessageChannel port.
  if (event.data && event.data.type === 'PWA_INSTALL_CHECK') {
    if (event.ports && event.ports[0]) {
      event.ports[0].postMessage({ installed: pwaInstalled });
    }
  }
});

clientsClaim();

// ============================================
// PRECACHING
// ============================================
// The placeholder below is replaced at build time by workbox-cli
// injectManifest with the list of revisioned URLs.
precacheAndRoute(self.__WB_MANIFEST, {
  ignoreURLParametersMatching: [/^utm_/, /^fbclid$/],
});
cleanupOutdatedCaches();

// ============================================
// JXL IMAGE ROUTE — decode .jxl via WASM, serve a renderable BMP
// ============================================
// Card art is one .jxl per card. The browser can't decode JXL (here), so we
// intercept every .jxl request, fetch the whole file, and route the bytes to the
// JXL decode worker pool (via the page) for a full-resolution decode.
//
// Query param:
//   ?d=<px>  downscale target — longest output side in pixels (0 = full).
//            Grid tiles pass ?d=512 (tile-sized); the detail view omits it.
//
// Decoded outputs are cached so revisits/scroll-back are instant: grid
// thumbnails (small, many) and full detail images (large, few) live in separate
// caches, each FIFO-capped so memory stays bounded. The small raw .jxl is also
// cached for offline re-decode.
// -v2: bumped when the WASM decoder changed (alpha→white composite) so the old
// black-on-transparent BMPs are re-decoded rather than served from cache.
const DECODED_CACHE = 'kipukas-images-decoded-v2'; // thumbnails (?d=512)
const FULL_CACHE = 'kipukas-images-full-v2'; // full detail decodes (no ?d)
const RAW_JXL_CACHE = 'kipukas-jxl';
const THUMB_CACHE_MAX = 300; // ~small BMPs
const FULL_CACHE_MAX = 12; // ~3.8MB BMP each → bounded ≈ 46MB

// Warm the offline cache after the user installs the PWA (triggered by
// install_pwa.html). Pulls the deferred assets — listed in offline-manifest.json
// — into the same runtime caches the request handlers read from, so a later
// offline session works fully. Idempotent (skips already-cached entries) and
// resumable; every fetch is best-effort so a single failure never aborts the run.
async function warmOfflineCache() {
  let manifest;
  try {
    const res = await fetch('/offline-manifest.json', { cache: 'no-store' });
    if (!res.ok) return;
    manifest = await res.json();
  } catch (_e) {
    return; // offline at warm time — nothing to do; we'll retry on next launch
  }

  const warmOne = async (url, cache, key) => {
    try {
      if (await cache.match(key || url)) return; // already warmed — skip
      const r = await fetch(url);
      if (r.ok) await cache.put(key || url, r.clone());
    } catch (_e) { /* best-effort; offline/quota — non-fatal */ }
  };

  // 1. QR decoder etc. — small, into the StaleWhileRevalidate assets cache.
  const assets = await caches.open('kipukas-assets');
  for (const url of (manifest.extra || [])) {
    await warmOne(url, assets);
  }
  // 2. Card art — the raw .jxl, keyed by absolute origin+path to match the JXL
  //    handler's offline cache lookup (rawCache.match(url.origin + url.pathname)).
  //    Sequential to avoid saturating a metered connection (it's ~tens of MB).
  const raw = await caches.open(RAW_JXL_CACHE);
  for (const path of (manifest.images || [])) {
    const abs = new URL(path, self.location.origin).href;
    await warmOne(abs, raw, abs);
  }
}

// Put into a cache, then evict oldest entries (insertion order) over the cap.
async function cachePutCapped(cache, request, response, max) {
  try {
    await cache.put(request, response);
    const keys = await cache.keys();
    for (let i = 0; i < keys.length - max; i++) {
      await cache.delete(keys[i]);
    }
  } catch (_e) { /* quota / eviction race — non-fatal */ }
}

// In-flight decode de-duplication: the card detail page requests the same .jxl
// three times at once (two <img> + one CSS background). Collapse identical
// concurrent requests onto a single decode and share the resulting bytes.
const jxlInflight = new Map();

const jxlMatcher = ({ url }) => url.pathname.endsWith('.jxl');

/// Fetch the whole .jxl and decode it (downscaled to maxDim), returning BMP bytes.
async function decodeJxlRequest(request, event) {
  const url = new URL(request.url);
  const maxDim = parseInt(url.searchParams.get('d') || '0', 10);

  // Fetch the whole file; cache the (small) raw .jxl for offline re-decode.
  const assetUrl = url.origin + url.pathname;
  const rawCache = await caches.open(RAW_JXL_CACHE);
  let buf;
  try {
    const net = await fetch(assetUrl);
    if (net.ok) {
      try { await rawCache.put(assetUrl, net.clone()); } catch (_e) { /* quota */ }
      buf = await net.arrayBuffer();
    }
  } catch (_e) { /* offline — fall through to cache */ }
  if (!buf) {
    const cachedRaw = await rawCache.match(assetUrl);
    if (cachedRaw) buf = await cachedRaw.arrayBuffer();
  }
  if (!buf) return null;

  // Relay bytes to the page → decode worker pool → WASM for decode.
  const client =
    (event.clientId && (await self.clients.get(event.clientId))) ||
    (await self.clients.matchAll({ type: 'window' }))[0];
  if (!client) return { raw: buf }; // no page to decode through (very first load)

  const bmp = await new Promise((resolve, reject) => {
    const channel = new MessageChannel();
    const timeout = setTimeout(() => reject(new Error('JXL decode timed out')), 15000);
    channel.port1.onmessage = (msg) => {
      clearTimeout(timeout);
      msg.data.ok ? resolve(msg.data.bytes) : reject(new Error(msg.data.error));
    };
    client.postMessage(
      { type: 'WASM_DECODE_JXL', bytes: buf, maxDim },
      [buf, channel.port2],
    );
  });
  return { bmp, maxDim };
}

const jxlHandler = async ({ request, event }) => {
  const hasDownscale = new URL(request.url).searchParams.has('d');
  // Thumbnails (?d=) and full detail images cache separately, each capped.
  const cache = await caches.open(hasDownscale ? DECODED_CACHE : FULL_CACHE);

  // 1. Decoded-output cache (keyed by the full request incl. ?d=). This is what
  //    makes revisits instant — full detail decodes are now cached too.
  const hit = await cache.match(request);
  if (hit) return hit;

  // 2. Decode (de-duplicating identical concurrent requests).
  const key = request.url;
  let result;
  try {
    if (jxlInflight.has(key)) {
      result = await jxlInflight.get(key);
    } else {
      const p = decodeJxlRequest(request, event);
      jxlInflight.set(key, p);
      try { result = await p; } finally { jxlInflight.delete(key); }
    }
  } catch (_e) {
    return Response.error();
  }
  if (!result) return Response.error();

  // 3. Build the response. Each caller gets a fresh Response from the bytes.
  if (result.raw) {
    return new Response(result.raw, { headers: { 'Content-Type': 'image/jxl' } });
  }
  const resp = new Response(result.bmp, {
    status: 200,
    headers: { 'Content-Type': 'image/bmp' },
  });
  await cachePutCapped(
    cache,
    request,
    resp.clone(),
    hasDownscale ? THUMB_CACHE_MAX : FULL_CACHE_MAX,
  );
  return resp;
};

registerRoute(jxlMatcher, jxlHandler);

// ============================================
// RUNTIME CACHING STRATEGIES
// ============================================

// Strategy 1: HTML Pages — NetworkFirst (fresh content is critical)
registerRoute(
  /\.(?:html)$/,
  new NetworkFirst({
    cacheName: 'kipukas-pages',
    networkTimeoutSeconds: 3,
    matchOptions: { ignoreSearch: true },
    plugins: [
      {
        cacheWillUpdate: async ({ response }) =>
          response && response.status === 200 ? response : null,
      },
    ],
  })
);

// The QR scanner's computer vision — CacheFirst. Its model (an .onnx file of
// about 10 MB) and what runs it (ONNX Runtime Web, from jsDelivr) are fetched
// only when a player turns computer vision on, and kept from then on so that
// it works offline. Neither changes under its address: a model trained again
// is another file (MODEL in kipukas-server/src/routes/qr.rs), and the
// runner's address names its version. The page may ask for a second copy of
// the runner under the same address with a query (yolo-inference.js), so the
// query is left out of what is kept and looked up.
registerRoute(
  ({ url }) =>
    (url.origin === self.location.origin && url.pathname.endsWith('.onnx')) ||
    (url.origin === 'https://cdn.jsdelivr.net' && url.pathname.startsWith('/npm/onnxruntime-web@')),
  new CacheFirst({
    cacheName: 'kipukas-vision',
    matchOptions: { ignoreSearch: true },
    plugins: [
      {
        cacheWillUpdate: async ({ response }) =>
          response && response.status === 200 ? response : null,
        cacheKeyWillBeUsed: async ({ request }) => {
          const url = new URL(request.url);
          url.search = '';
          return url.href;
        },
      },
      new ExpirationPlugin({
        // A model and the runner's three files, twice over: room for the
        // new ones when either is replaced, after which the old ones go.
        maxEntries: 8,
        purgeOnQuotaError: true,
      }),
    ],
  })
);

// Strategy 2: Static Assets (CSS, JS, WASM) — StaleWhileRevalidate
registerRoute(
  /\.(?:css|js|wasm)$/,
  new StaleWhileRevalidate({
    cacheName: 'kipukas-assets',
    plugins: [
      {
        cacheWillUpdate: async ({ response }) =>
          response && response.status === 200 ? response : null,
      },
      new ExpirationPlugin({
        maxEntries: 200,
        maxAgeSeconds: 30 * 24 * 60 * 60, // 30 days
        purgeOnQuotaError: true,
      }),
    ],
  })
);

// Strategy 3: Images — CacheFirst (images rarely change)
registerRoute(
  /\.(?:png|jpg|jpeg|svg|gif|webp|ico)$/,
  new CacheFirst({
    cacheName: 'kipukas-images',
    plugins: [
      {
        cacheWillUpdate: async ({ response }) =>
          response && response.status === 200 ? response : null,
      },
      new ExpirationPlugin({
        maxEntries: 500,
        maxAgeSeconds: 60 * 24 * 60 * 60, // 60 days
        purgeOnQuotaError: true,
      }),
    ],
  })
);

// Strategy 4: Google Fonts — CacheFirst with long expiration
registerRoute(
  /^https:\/\/fonts\.(?:googleapis|gstatic)\.com\/.*/i,
  new CacheFirst({
    cacheName: 'kipukas-fonts',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 30,
        maxAgeSeconds: 365 * 24 * 60 * 60, // 1 year
      }),
    ],
  })
);

// ============================================
// CLEANUP: remove old versioned runtime caches from the previous setup
// ============================================
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) =>
      Promise.all(
        cacheNames
          .filter((name) => {
            // Delete any old runtime caches that contain a version hash
            // (the old format was kipukas-{type}-{hash}_{date})
            const isOldVersionedCache =
              name.startsWith('kipukas-') &&
              /kipukas-(?:pages|assets|images|fonts)-[a-f0-9]{64}/.test(name);
            // Also delete the old "my-app-cache-" prefix from the backup config
            const isLegacyCache = name.startsWith('my-app-cache-');
            // Pre-v2 decoded-image caches held BMPs from the old decoder (alpha
            // dropped → black). Drop them so the new decoder's output is used.
            const isStaleDecodedCache =
              name === 'kipukas-images-decoded' || name === 'kipukas-images-full';
            return isOldVersionedCache || isLegacyCache || isStaleDecodedCache;
          })
          .map((name) => {
            console.log('[SW] Deleting old cache:', name);
            return caches.delete(name);
          })
      )
    )
  );
});
